<template>
  <div>
    <el-button
      type="primary"
      plain
      icon="el-icon-plus"
      size="mini"
      @click="addRules"
      >新增算法</el-button
    >
    <el-table :data="tableData" style="width: 100%" v-loading="loading">
      <el-table-column prop="ai_code" label="报警编号" align="center">
      </el-table-column>
      <el-table-column prop="ai_name" label="算法名称" align="center">
      </el-table-column>
      <el-table-column label="操作" align="center">
        <template slot-scope="scope">
          <el-button type="text" @click="chooseType(scope.row, 1)">
            <i title="选择模型分类" class="icon iconf-model fs-14"></i>
          </el-button>
          <el-button
            type="text"
            @click="editData(scope.row)"
            class="el-icon-edit"
          ></el-button>
          <el-button
            type="text"
            @click="delData(scope.row)"
            class="el-icon-delete"
            style="color: red"
          ></el-button>
        </template>
      </el-table-column>
    </el-table>
    <pagination
      class="float-right mt-10"
      v-show="total > 0"
      :total="total"
      :page.sync="params.page"
      :limit.sync="params.size"
      @pagination="getDataList"
      layout="total, prev, pager, next"
      small
    />
    <el-dialog
      :title="title"
      :visible.sync="rulesVisible"
      width="45%"
      append-to-body
    >
      <el-form :model="form" label-width="150px" ref="form" :rules="rules">
        <el-form-item label="报警编号" prop="ai_code">
          <el-input v-model="form.ai_code" style="width: 300px" />
        </el-form-item>
        <el-form-item label="算法名称" prop="ai_name">
          <el-input v-model="form.ai_name" style="width: 300px" />
        </el-form-item>
        <el-form-item label="算法类型" prop="ai_type">
          <el-select v-model="form.ai_type" @change="changeType" clearable>
            <el-option label="对象滞留" :value="1"></el-option>
            <el-option label="对象聚集" :value="2"></el-option>
            <el-option label="人脸识别" :value="3"></el-option>
            <el-option label="人员跌倒" :value="4"></el-option>
            <el-option label="车牌识别" :value="5"></el-option>
          </el-select>
        </el-form-item>
        <el-form-item
          label="滞留时间"
          prop="ai_type_param"
          v-if="form.ai_type == 1"
        >
          <el-input-number
            class="mr-10"
            v-model="form.ai_type_param"
          ></el-input-number>
          秒
          <div style="color: red">超过滞留时间将会报警</div>
        </el-form-item>
        <el-form-item
          label="对象超过"
          prop="ai_type_param"
          v-if="form.ai_type == 2"
        >
          <el-input-number
            class="mr-10"
            v-model="form.ai_type_param"
          ></el-input-number>
          个
        </el-form-item>
        <template v-if="form.ai_type == 3">
          <el-form-item label="">
            <el-radio-group v-model="form.ai_type_param">
              <el-radio :label="1">外来人员闯入报警</el-radio>
              <el-radio :label="2">黑名单报警</el-radio>
            </el-radio-group>
          </el-form-item>
        </template>
        <el-form-item label="报警声音" prop="ai_audio_id">
          <el-select
            v-model="form.ai_audio_id"
            placeholder="请选择音频"
            clearable
          >
            <el-option label="无声音" :value="0"></el-option>
            <el-option
              v-for="audio in audioList"
              :key="audio.id"
              :label="audio.name"
              :value="audio.id"
            ></el-option>
          </el-select>
        </el-form-item>
      </el-form>
      <div slot="footer" class="dialog-footer">
        <el-button type="primary" @click="submitForm('form')">确认</el-button>
        <el-button @click="rulesVisible = false">取消</el-button>
      </div>
    </el-dialog>
    <el-dialog
      title="模型类型列表"
      :visible.sync="modelVisible"
      width="65%"
      append-to-body
      top="10px"
      @open="getDataAiModelClassList"
      @close="getAllDataAiModelClassList"
    >
      <div class="d-flex">
        <el-tabs
          tab-position="left"
          @tab-click="chooseModel"
          v-model="modelName"
        >
          <el-tab-pane
            :label="item.model_name"
            v-for="(item, index) in modelList"
            :key="item.model_id"
            :name="index.toString()"
          >
            <el-checkbox-group size="small" v-model="checkedTabs">
              <el-checkbox
                @change="handleCheckedTabs"
                v-for="value in modelClassList"
                :label="value.id"
                :key="value.id"
                border
                :disabled="value.checked"
                >{{ value.class_name }}</el-checkbox
              >
            </el-checkbox-group>
          </el-tab-pane>
        </el-tabs>
      </div>
    </el-dialog>
  </div>
</template>

<script>
export default {
  data() {
    return {
      tableData: [],
      title: "新增算法",
      rulesVisible: false,
      form: {},
      analyseList: [
        {
          name: "车辆类型识别",
          type: 1,
        },
        {
          name: "车牌识别",
          type: 2,
        },
        {
          name: "火焰烟雾识别",
          type: 3,
        },
      ],
      params: {
        page: 1,
        size: 10,
      },
      total: 0,
      classList: [],
      loading: false,
      modelVisible: false,
      modelClassList: [],
      modelList: [],
      modelForm: {},
      modelName: "0",
      AiModelClassList: [],
      modelObj: {},
      checkedTabs: [],
      rules: {
        ai_code: [{ required: true, message: "请输入", trigger: "blur" }],
        ai_name: [{ required: true, message: "请输入", trigger: "blur" }],
      },
      audioList: [],
    };
  },
  created() {
    this.getDataList();
    this.getmodalList();
    this.getAllDataAiModelClassList();
    this.getAudioList();
  },
  methods: {
    getAudioList() {
      this.$api.get("/audio/getSysAudioList").then((res) => {
        if (res.data.data) {
          this.audioList = res.data.data;
        }
      });
    },
    changeType(e) {
      if (e == 1) {
        this.$set(this.form, "ai_type_param", 30);
      } else if (e == "") {
        this.$set(this.form, "ai_type_param", undefined);
        this.$set(this.form, "ai_type", undefined);
      } else if (e == 3) {
        this.$set(this.form, "ai_type_param", 1);
      } else {
        this.$set(this.form, "ai_type_param", 5);
      }
    },
    handleCheckedTabs(checked, e) {
      let class_id = Number(e.target.value);
      const url = checked
        ? "/ai/addDataAiModelClass"
        : "/ai/delDataAiModelClass";
      this.$api
        .post(url, {
          ai_id: this.modelForm.id,
          class_id,
        })
        .then(() => {
          // this.$message.success("操作成功");
        })
        .catch(() => {
          this.checkedTabs = this.checkedTabs.filter(
            (item) => item !== class_id,
          );
        });
    },
    // 模型列表获取 id
    getDataAiModelClassList() {
      this.checkedTabs = [];
      this.$api
        .get("/ai/getDataAiModelClassList", {
          params: { ai_id: this.modelForm.id },
        })
        .then((res) => {
          if (res.data.data) {
            this.checkedTabs = res.data.data.map((item) => item.class_id);
            this.getDataModelClassList();
          }
        });
    },
    // 查询全部模型与ai关系
    getAllDataAiModelClassList() {
      this.$api.get("/ai/getDataAiModelClassList").then((res) => {
        this.AiModelClassList = res.data.data;
      });
    },
    // 选择模型
    chooseModel(e) {
      this.modelObj = this.modelList[e.index];
      this.getDataModelClassList();
    },
    // 模型列表
    getmodalList() {
      this.$api
        .get("/ai/getDataModelList", { params: { model_status: 1 } })
        .then((res) => {
          this.modelList = res.data.data;
          this.modelObj = this.modelList[0];
          this.getDataModelClassList();
        });
    },
    // 选择类
    chooseClass(val, data) {
      const url =
        val.indexOf(data) > -1
          ? "/ai/addDataAiModelClass"
          : "/ai/delDataAiModelClass";
      this.$api
        .post(url, {
          ai_id: this.modelForm.id,
          class_id: data.id,
        })
        .then(() => {
          this.$message.success("操作成功");
        });
    },
    //根据模型查分类
    getDataModelClassList() {
      this.$api
        .get(`/ai/getDataModelClassList`, {
          params: {
            model_id: this.modelObj.id,
          },
        })
        .then((res) => {
          this.modelClassList = res.data.data;
          // this.processData(
          //   this.AiModelClassList,
          //   res.data.data
          // );
        });
    },
    processData(data, data1) {
      const classIdSet = new Set(data.map((item) => item.id));
      const targetClassSet = new Set(this.checkedTabs);
      // 如果别的存在在别的算法下面或者不存在当前算法下面就可以勾选
      return data1.map((item) => ({
        ...item,
        checked: classIdSet.has(item.id) && !targetClassSet.has(item.id),
      }));
    },

    // 选择分类按钮（算法列表）
    chooseType(row) {
      this.modelForm = row;
      this.modelVisible = true;
      // this.getDataAiModelClassList();
    },
    delClassItem(index) {
      this.classList.splice(index, 1);
    },
    delData(item) {
      this.$confirm("是否删除该数据?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(() => {
          this.$api
            .post("/ai/delDataAi", {
              id: item.id,
            })
            .then(() => {
              this.$message.success("操作成功");
              this.getDataList();
            });
        })
        .catch(() => {
          this.$message({
            type: "info",
            message: "已取消删除",
          });
        });
    },
    editData(row) {
      this.title = "编辑算法";
      this.rulesVisible = true;
      this.form = {
        ...row,
        ai_type: row.ai_type == 0 ? undefined : row.ai_type,
      };
      this.classList = this.form.class_name
        ? JSON.parse(this.form.class_name).map((item) => ({ text: item }))
        : [];
    },
    addRules() {
      this.form = {};
      this.classList = [];
      this.rulesVisible = true;
    },
    changeAIType(e) {
      this.form.ai_type_alias = e.name;
      this.form.ai_type = e.type;
    },
    submitForm(formName) {
      this.form.ai_code = Number(this.form.ai_code);
      this.$refs[formName].validate((valid) => {
        if (valid) {
          this.form.ai_audio_id = this.form.ai_audio_id
            ? this.form.ai_audio_id
            : 0;
          if (this.form.id) {
            this.$api.post("/ai/updateDataAi", this.form).then(() => {
              this.rulesVisible = false;
              this.$message.success("操作成功");
              this.getDataList();
            });
          } else {
            this.$api.post("/ai/addDataAi", this.form).then(() => {
              this.rulesVisible = false;
              this.$message.success("操作成功");
              this.getDataList();
            });
          }
        } else {
          return false;
        }
      });
    },
    getDataList() {
      this.loading = true;
      this.$api
        .get(`/ai/getDataAiList`, { params: this.params })
        .then((res) => {
          if (res.data.data) {
            this.tableData = res.data.data;
            this.total = res.data.total;
          }
        })
        .finally(() => {
          this.loading = false;
        });
    },
  },
};
</script>
<style lang="less" scoped>
::v-deep(.el-dialog) {
  overflow-x: hidden !important;
}

::v-deep .el-table--small {
  .el-table__cell {
    padding: 5px 0 !important;
  }
}
::v-deep .el-checkbox.is-bordered.el-checkbox--small {
  margin: 0 15px 15px 0 !important;
}
::v-deep .el-checkbox.is-bordered.el-checkbox--small {
  width: 110px;
}
</style>
<style lang="scss">
.el-table__header-wrapper {
  .el-checkbox__inner {
    display: none !important;
  }
}
</style>
